      n: rn,
      s: {
        shape, rank, polarity: (LETTER_POL[pol] || "Madurai").toLowerCase(),
        bonuses: (bonuses || []).map(([id, roll]) => ({ id, roll })),
        malus: malus ? { id: malus[0], roll: malus[1] } : null,
      },
